// The judge provides: int read4(char *buf4);
class Solution
{
    char tmp[4];
    int pos = 0, len = 0;
public:
    int read(char*buf, int n)
    {
        int used = 0;
        while (used < n)
        {
            if (pos == len)
            {
                len = read4(tmp);
                pos = 0;
                if (!len)
                {
                    break;
                }
            }
            buf[used++] = tmp[pos++];
        }
        return used;
    }
};
